local FluteMaker = {}
local PRODUCTS = {
    simple_reed_flute = { name = "Preprosta trstna flavta", woodCost = 1, time = 2, cost = 25, music = 18, happiness = 1, description = "Preprosta trstna flavta za pastirje." },
    wooden_recorder = { name = "Leseni blokflavta", woodCost = 2, time = 4, cost = 70, music = 32, happiness = 2, prestige = 1, description = "Leseni blokflavta za trgovce." },
    boxwood_consort_flute = { name = "Pušpanova flavta", woodCost = 3, leatherCost = 1, time = 7, cost = 200, music = 48, happiness = 2, prestige = 4, description = "Pušpanova flavta za plemiče." },
    silver_banded_flute = { name = "Srebrnopasna flavta", woodCost = 2, silverCost = 1, leatherCost = 1, time = 10, cost = 540, music = 62, happiness = 3, prestige = 12, description = "Srebrnopasna flavta za visoke plemiče." },
    gold_trimmed_flute = { name = "Zlatookrasna flavta", woodCost = 3, goldCost = 1, silverCost = 1, leatherCost = 1, jewelCost = 1, time = 14, cost = 1300, music = 78, happiness = 5, prestige = 25, description = "Zlatookrasna flavta z draguljem za visoko plemstvo." },
    royal_grand_flute = { name = "Kraljevski veliki flavta", woodCost = 4, goldCost = 2, silverCost = 2, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 21, cost = 3300, music = 92, happiness = 11, prestige = 56, description = "Velika kraljevska flavta z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    flute_workshop = { name = "Flavtna delavnica", cost = { gold = 200, wood = 120, stone = 80, leather = 6 }, upkeep = 4, qualityBonus = 5 },
    woodwind_loft = { name = "Podstrešje za pihala", cost = { gold = 780, wood = 240, stone = 220, silver = 6, leather = 8 }, upkeep = 18, qualityBonus = 18 },
    master_wind_atelier = { name = "Mojstrski pihalni atelje", cost = { gold = 2300, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 52, qualityBonus = 30 },
    royal_flute_palace = { name = "Kraljevska flavtna palača", cost = { gold = 9500, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 50 },
}
FluteMaker.woodStock = 18; FluteMaker.leatherStock = 10; FluteMaker.silverStock = 6; FluteMaker.goldStock = 6; FluteMaker.jewelStock = 4; FluteMaker.pearlStock = 4
FluteMaker.productStock = {}; FluteMaker.buildings = {}; FluteMaker.maker = nil; FluteMaker.activeMaking = {}; FluteMaker.totalProducts = 0; FluteMaker.dayTimer = 0
function FluteMaker.init() FluteMaker.woodStock=18; FluteMaker.leatherStock=10; FluteMaker.silverStock=6; FluteMaker.goldStock=6; FluteMaker.jewelStock=4; FluteMaker.pearlStock=4; FluteMaker.productStock={}; FluteMaker.buildings={}; FluteMaker.maker=nil; FluteMaker.activeMaking={}; FluteMaker.totalProducts=0; FluteMaker.dayTimer=0; print("[FluteMaker] Royal Flute Maker System initialized (6 products, 4 buildings)") end
function FluteMaker.hireMaker(n,s) s=s or math.random(55,90); local c=460+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FluteMaker.maker={name=n or ("Flavtar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Flavtar najet: %s (spretnost: %d)",FluteMaker.maker.name,s),"success") end; return true end
function FluteMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FluteMaker.build(id) local ok,e=FluteMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FluteMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FluteMaker.getQualityBonus() local b=0; for _,bd in ipairs(FluteMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FluteMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and FluteMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and FluteMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and FluteMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FluteMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FluteMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FluteMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FluteMaker.buildings==0 then return false,"Potrebna flavtna delavnica" end; if not FluteMaker.maker then return false,"Potreben flavtar" end; return true end
function FluteMaker.make(pt,qty) qty=qty or 1; local ok,e=FluteMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then FluteMaker.woodStock=FluteMaker.woodStock-d.woodCost*qty end; if d.leatherCost then FluteMaker.leatherStock=FluteMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then FluteMaker.silverStock=FluteMaker.silverStock-d.silverCost*qty end; if d.goldCost then FluteMaker.goldStock=FluteMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FluteMaker.jewelStock=FluteMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FluteMaker.pearlStock=FluteMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FluteMaker.maker then t=math.max(1,t-math.floor(FluteMaker.maker.skill/13)) end; table.insert(FluteMaker.activeMaking,{id="flute_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,music=d.music or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FluteMaker.completeMaking(m) local q=1.0+(FluteMaker.getQualityBonus()/100); if FluteMaker.maker then q=q+(FluteMaker.maker.skill/150) end; q=math.min(2.4,q); FluteMaker.productStock[m.productType]=(FluteMaker.productStock[m.productType] or 0)+m.quantity; FluteMaker.totalProducts=FluteMaker.totalProducts+m.quantity; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if FluteMaker.maker then FluteMaker.maker.itemsMade=FluteMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FluteMaker.maker.skill=math.min(100,FluteMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Flavta izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"flute.completed",{productName=m.productName,music=m.music,prestige=m.prestige,happiness=m.happiness}) end end
function FluteMaker.update(dt) if not _G.state then return end; FluteMaker.dayTimer=FluteMaker.dayTimer+dt; if FluteMaker.dayTimer>=30 then FluteMaker.dayTimer=0; for i=#FluteMaker.activeMaking,1,-1 do local m=FluteMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FluteMaker.completeMaking(m); table.remove(FluteMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FluteMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FluteMaker.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FluteMaker.getStats() return {woodStock=FluteMaker.woodStock,leatherStock=FluteMaker.leatherStock,silverStock=FluteMaker.silverStock,goldStock=FluteMaker.goldStock,jewelStock=FluteMaker.jewelStock,pearlStock=FluteMaker.pearlStock,productStock=FluteMaker.productStock,numBuildings=#FluteMaker.buildings,hasMaker=FluteMaker.maker~=nil,makerName=FluteMaker.maker and FluteMaker.maker.name or "—",makerSkill=FluteMaker.maker and FluteMaker.maker.skill or 0,activeMaking=#FluteMaker.activeMaking,totalProducts=FluteMaker.totalProducts} end
return FluteMaker
